// Presenter scenarios built from the promoted resolver release. Every record
// value, candidate route, Splink comparison weight, probability, decision and
// decision reason comes from release-evidence.js (generated by
// apps/identity-presenter/extract_release_evidence.py). This file only adds
// presenter copy: titles, tab labels and the plain-language rule explanations.
const releaseEvidence=window.IDENTITY_RELEASE_EVIDENCE;

// Splink comparisons in model order, with the SQL that decomposes the stored
// Bayes factors in match_decisions into per-field match weights.
const comparisonFields={
  name_n:{label:'Name',column:'full_name',alias:'w_name',sql:'log2(bf_name_n * bf_tf_adj_name_n)'},
  personal_email_n:{label:'Personal email',column:'personal_email',alias:'w_email',sql:'log2(bf_personal_email_n * bf_tf_adj_personal_email_n)'},
  personal_phone_n:{label:'Personal phone',column:'personal_phone',alias:'w_phone',sql:'log2(bf_personal_phone_n * bf_tf_adj_personal_phone_n)'},
  dob_usable:{label:'Date of birth',column:'date_of_birth',alias:'w_dob',sql:'log2(bf_dob_usable)'},
  home_address_n:{label:'Home address',column:'home_address',alias:'w_address',sql:'log2(bf_home_address_n * bf_tf_adj_home_address_n)'}
};

// Presenter copy per scenario. `rule` explains the decide_v4 match-policy clause
// that fired (resolution/splink_v4/policy.py); {p} and {w} are filled from the
// release's model probability and match weight.
const scenarioCopy={
  'preferred-name':{short:'Preferred name',subtitle:'English + Chinese name',title:'Can English and Chinese names belong to one guest?',
    rule:'Model probability {p} (match weight {w}): the name, email and address comparisons disagree, so Splink stays low. An exact personal phone plus a matching birth date is sufficient under the match policy, so the policy, not the model alone, links this pair.',
    notes:{home_address_n:'Different scripts, so the string comparison cannot agree. AI Search still found the pair through this address.'}},
  corporate:{short:'Corporate',subtitle:'Shared organiser details',title:'Do shared company contacts identify the same person?',
    // Shared work fields made this pair a candidate; Splink does not score them.
    context:[['work_email','work_email'],['work_phone','work_phone'],['work_address','work_address']],
    rule:'Two valid, different birth dates are a hard contradiction, so the pair is rejected before any other rule. The shared work email, phone and address only made them a candidate; they are not Splink comparisons. Model probability {p}.',
    notes:{}},
  household:{short:'Household',subtitle:'Parent and child',title:'Do household details prove these are one person?',
    rule:'Two valid, different birth dates are a hard contradiction, so the household stays split. The shared address counts for the model and the shared home phone is excluded, but neither can override the birth dates. Model probability {p}.',
    notes:{}},
  'default-dob':{short:'Default DOB',subtitle:'Source placeholder',title:'Should a source-default birthday block a strong match?',
    rule:'The personal email and personal phone both match exactly and the names agree, which the match policy accepts. The source-default birth date is excluded, so it neither supports nor blocks the link. Model probability {p}.',
    notes:{}},
  sparse:{short:'Sparse typo',subtitle:'ANN-only candidate',title:'Is this sparse typo-heavy candidate safe to link?',
    rule:'No guessing: model probability {p}. The address is close and AI Search ranked the pair first, but the typo-heavy name disagrees and the sparse record has no email, phone or birth date. Too little evidence to link, so it stays its own profile and can be linked later when new evidence arrives.',
    notes:{}},
  duplicate:{short:'Duplicate',subtitle:'Within one source',title:'Are these duplicate records inside one source?',
    rule:'An exact personal contact plus a matching birth date meets the match policy, and every Splink comparison agrees (model probability {p}). Duplicates inside one source are linked like any other pair.',
    notes:{}},
  review:{short:'Needs review',subtitle:'Probable match, no contact',title:'Is a 99% model score enough to merge two guests?',
    rule:'Model probability {p}: the exact name and near-identical address carry the score. But the payments record has no email, phone or birth date, and the policy only merges automatically on independent personal evidence. Instead of guessing, the pipeline hands the pair to a steward.',
    notes:{}}
};

const blockNames={PERSONAL_EMAIL:'personal email',PERSONAL_PHONE:'personal phone',PHONE_SUFFIX:'phone suffix',WORK_EMAIL:'work email',WORK_PHONE:'work phone',
  HOME_ADDRESS:'home address',WORK_ADDRESS:'work address',FAMILY_DOB:'family name + DOB',FAMILY_INITIAL_POSTCODE:'family name + initial + postcode'};

const formatWeight=w=>Math.abs(w)<.005?'0.00':`${w<0?'−':'+'}${Math.abs(w).toFixed(2)}`;
const formatScore=s=>s.toFixed(2);
function formatProbability(p){
  if(p>=.9999)return '>99.99%';
  if(p<.0001)return '<0.01%';
  if(p<.01)return `${(p*100).toFixed(2)}%`;
  return `${(p*100).toFixed(1).replace(/\.0$/,'')}%`;
}
function shortId(id){return id.length>10?`${id.slice(0,8)}…`:id}
function addressValue(r){const parts=[r.home_address_line1,r.home_suburb].filter(Boolean);return parts.length?parts.join(', '):null}
function visibleValue(r,column){
  if(column==='home_address')return addressValue(r);
  if(column==='work_address'){const parts=[r.work_address_line1,r.work_suburb].filter(Boolean);return parts.length?parts.join(', '):null}
  return r[column];
}

function routeSummary(c,left){
  const ann=[['name',c.ann_name_rank,c.ann_name_score],['address',c.ann_address_rank,c.ann_address_score]].filter(x=>x[1]!==null);
  const blocks=c.reasons.filter(r=>!r.startsWith('ANN_'));
  const parts=[];
  if(ann.length)parts.push(`AI Search ${ann.map(([kind,rank,score])=>`${kind} #${rank} (${formatScore(score)})`).join(', ')}`);
  if(blocks.length)parts.push(`${blocks.length} deterministic block${blocks.length>1?'s':''}`);
  const detail=[];
  const shared={WORK_EMAIL:left.work_email,WORK_PHONE:left.work_phone,WORK_ADDRESS:left.work_address_line1};
  if(blocks.length)detail.push(`Found by ${blocks.length} blocking rule${blocks.length>1?'s':''} (${blocks.map(b=>(blockNames[b]||b.toLowerCase())+(shared[b]?` ${shared[b]}`:'')).join(', ')})${ann.length?' and by':'.'}`);
  if(ann.length)detail.push(`${blocks.length?'':'Found by '}AI Search (${ann.map(([kind,rank,score])=>`${kind} neighbour #${rank}, similarity ${score.toFixed(3)}`).join('; ')}).`);
  return {route:parts.join(' + '),detail:detail.join(' ')};
}

function levelShort(label){
  const m=label.match(/>=\s*([\d.]+)/);
  return m?`Similar ≥ ${m[1]}`:label;
}

// Classify one Splink comparison for the evidence log. A comparison Splink saw
// as Missing is "excluded" when both sources hold a value that the truth-blind
// contact profile removed (a shared contact or a source-default birth date).
function fieldEvidence(s,c,copy){
  const def=comparisonFields[c.column],left=s.left,right=s.right,f=s.features;
  const raw=[visibleValue(left,def.column),visibleValue(right,def.column)];
  const which=raw[0]===null&&raw[1]===null?'either record':raw[0]===null?`the ${left.source_system} record`:`the ${right.source_system} record`;
  let kind,result,detail;
  if(c.gamma===-1){
    const sharedPhone=c.column==='personal_phone_n'&&(left.profile.phone_is_shared||right.profile.phone_is_shared);
    const sharedEmail=c.column==='personal_email_n'&&(left.profile.email_is_shared||right.profile.email_is_shared);
    const defaultDob=c.column==='dob_usable'&&(left.profile.dob_is_source_default||right.profile.dob_is_source_default);
    if(sharedPhone||sharedEmail){
      kind='ignored';result=`Excluded, shared contact · ${formatWeight(c.weight)}`;
      detail='Profiled as shared (its users have different birth dates), so it is not personal evidence.';
    }else if(defaultDob){
      const dflt=left.profile.dob_is_source_default?left:right;
      kind='ignored';result=`Excluded, source default · ${formatWeight(c.weight)}`;
      detail=`${dflt.date_of_birth} is a profiled source default in ${dflt.source_system}, so it is not evidence.`;
    }else{
      kind='insufficient';result=`No value · ${formatWeight(c.weight)}`;
      detail=`Missing on ${which}, so the comparison is neutral.`;
    }
  }else{
    result=`${levelShort(c.level)} · ${formatWeight(c.weight)}`;
    if(c.column==='dob_usable'&&f.dob_variant==='CONFLICT'){
      kind='reject';detail='Two valid birth dates differ: the VALID_DOB_CONFLICT safeguard.';
    }else{
      kind=c.weight>0?'support':'caution';
      if(c.level==='Exact')detail=`Normalised values match exactly${Math.abs(c.tf_adjustment-1)>1e-9?', adjusted for how common the value is':''}.`;
      else if(c.level==='Disagree')detail=f.cross_script&&(c.column==='name_n'||c.column==='home_address_n')?'Different scripts, so the string comparison cannot agree.':'Normalised values differ.';
      else detail=`Not exact; normalised edit similarity ${c.level.replace(/^Normalised edit similarity /,'').replace('>=','is at least')}.`;
    }
  }
  if(copy.notes[c.column])detail=copy.notes[c.column];
  return {kind,result,detail};
}

function buildScenario(s){
  const copy=scenarioCopy[s.key],route=routeSummary(s.candidate,s.left);
  let running=s.splink.prior_weight;
  const cols=s.splink.comparisons.map(c=>comparisonFields[c.column]);
  const fields=s.splink.comparisons.map((c,i)=>{
    const def=comparisonFields[c.column],ev=fieldEvidence(s,c,copy);running+=c.weight;
    return {label:def.label,column:def.column,splinkColumn:c.column,level:c.level,gamma:c.gamma,weight:c.weight,
      result:ev.result,kind:ev.kind,detail:ev.detail,
      // Worth showing on the ledger row: a scenario note, a safeguard or an excluded value.
      emphasis:Boolean(copy.notes[c.column])||ev.kind==='reject'||ev.kind==='ignored',
      sql:`${def.sql} AS ${def.alias}${i<s.splink.comparisons.length-1?',':''}`,
      value:`${def.alias} = ${formatWeight(c.weight)}`,
      running:`Running match weight ${formatWeight(running)}`};
  });
  const probability=formatProbability(s.splink.match_probability);
  const decisionClass=s.decision==='AUTO_MATCH'?'auto-match':s.decision==='REVIEW'?'review':s.decision_reason==='LOW_MATCH_PROBABILITY'?'separate':'reject';
  const outcome=s.decision==='AUTO_MATCH'?'Linked into one guest profile':s.decision==='REVIEW'?'Queued for a steward':'Kept separate';
  const context=copy.context||[];
  const record=r=>({source:r.source_system,id:shortId(r.source_record_id),recordId:r.source_record_id,values:cols.map(def=>visibleValue(r,def.column)),
    context:context.map(([,column])=>visibleValue(r,column))});
  return {key:s.key,context:context.map(([label])=>label),short:copy.short,subtitle:copy.subtitle,title:copy.title,
    route:route.route,routeDetail:route.detail,
    decision:s.decision,decisionClass,decisionRule:s.decision_reason,outcome,
    decisionReason:copy.rule.replace('{p}',probability).replace('{w}',formatWeight(s.splink.match_weight)),
    matchProbability:s.splink.match_probability,probabilityLabel:probability,
    matchWeight:s.splink.match_weight,priorWeight:s.splink.prior_weight,
    left:record(s.left),right:record(s.right),fields};
}

// The sparse typo pair is a real miss: the same guest, rejected and never sent to
// review. It stays in the release evidence (Act 1 uses its records) but is not shown
// as a decision scenario.
const scenarios=releaseEvidence.scenarios.filter(s=>s.key!=='sparse').map(buildScenario);

const evidenceKindLabels={support:'Supports a match',caution:'Counts against',reject:'Hard safeguard',ignored:'Excluded by profile',insufficient:'Missing, neutral'};
function evidenceKindLabel(kind){return evidenceKindLabels[kind]||kind}

window.IDENTITY_SCENARIOS=scenarios;

if(document.querySelector('.scenario-tabs')){

let activeIndex=0;
let runToken=0;
let timers=[];

function syntax(sql){return sql.replace(/^([a-z_][a-z0-9_]*)(?=\()/,'<em>$1</em>').replace(/\b(AS|AND|NOT|OR)\b/g,'<b>$1</b>')}
function table(s){return `<div class="record-table" data-table data-field="0"><div class="table-title"><b>selected_candidate_records</b></div><i class="column-highlight" data-column-highlight></i><div class="table-grid table-head"><span>source</span><span>record_id</span>${s.fields.map((f,i)=>`<span data-col="${i}">${f.label}</span>`).join('')}</div><div class="table-grid table-row"><b>${s.left.source}</b><code>${s.left.id}</code>${s.left.values.map((v,i)=>`<span data-col="${i}">${v===null?'<i class="null-value">null</i>':v}</span>`).join('')}</div><div class="table-grid table-row"><b>${s.right.source}</b><code>${s.right.id}</code>${s.right.values.map((v,i)=>`<span data-col="${i}">${v===null?'<i class="null-value">null</i>':v}</span>`).join('')}</div></div>`}
function sqlPanel(s){return `<div class="sql-panel"><div class="sql-head"><img src="assets/lakeflow-jobs-lockup-no-db-full-color.svg" alt="Lakeflow Jobs"></div><div class="sql-editor">${s.fields.map((f,i)=>`<div class="sql-line" data-sql-line="${i}"><i>${i+1}</i><code>${i===0?'<b>SELECT</b>&nbsp;&nbsp;':'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;'}${syntax(f.sql)}</code></div>`).join('')}</div></div>`}
function nav(s){return `<div class="field-nav">${s.fields.map((f,i)=>`<button data-field-button="${i}"><span class="stage-number">${i+1}</span><span class="stage-label">${f.label}</span><span class="stage-play">▶</span></button>`).join('')}</div>`}
function log(s){return `<aside class="log-panel"><div class="log-head"><b>Pair evidence</b><div><span data-log-progress>0 of ${s.fields.length} evaluated</span><strong data-decision-badge></strong></div></div><div class="log-body">${s.fields.map((f,i)=>`<article class="log-item ${f.kind}" data-log-item="${i}"><div class="log-kind"><i></i><span>${evidenceKindLabel(f.kind)}</span></div><strong>${f.result}</strong><p>${f.detail}</p></article>`).join('')}</div></aside>`}
function controls(s){return `<div class="scenario-control-rail">${nav(s)}<div class="scenario-run-actions"><button data-reset>Reset</button><button class="play" data-play><span>▶</span> Evaluate pair</button></div></div>`}
function stage(s){return `<section class="scenario-stage"><div class="scenario-heading"><div><h1>${s.title}</h1><p>${s.routeDetail}</p></div><span class="route-badge">${s.route}</span></div><div class="workspace"><div class="scan-layout stream-layout"><div class="left-stack">${table(s)}${sqlPanel(s)}</div>${log(s)}</div></div>${controls(s)}</section>`}

function renderTabs(){document.querySelector('.scenario-tabs').innerHTML=scenarios.map((s,i)=>`<button data-scenario="${i}" class="${i===activeIndex?'active':''}" aria-selected="${i===activeIndex}"><b>${i+1}</b><span>${s.short}<small>${s.subtitle}</small></span></button>`).join('')}
function renderScenario(){const s=scenarios[activeIndex];document.getElementById('root').innerHTML=stage(s);bindStage();requestAnimationFrame(()=>positionHighlight(0))}
function clearRun(){runToken+=1;timers.forEach(clearTimeout);timers=[];document.querySelectorAll('.result-flight').forEach(el=>el.remove())}
function positionHighlight(index){const tableEl=document.querySelector('[data-table]'),cell=tableEl?.querySelector(`.table-head [data-col="${index}"]`),highlight=tableEl?.querySelector('[data-column-highlight]');if(!cell||!highlight)return;const tr=tableEl.getBoundingClientRect(),cr=cell.getBoundingClientRect();highlight.style.left=`${cr.left-tr.left-1}px`;highlight.style.top=`${cr.top-tr.top-1}px`;highlight.style.width=`${cr.width+1}px`;highlight.style.height=`${tr.bottom-cr.top}px`}
function setField(index){const stageEl=document.querySelector('.scenario-stage'),tableEl=stageEl.querySelector('[data-table]');tableEl.dataset.field=String(index);stageEl.dataset.field=String(index);positionHighlight(index);stageEl.querySelectorAll('[data-field-button]').forEach((b,i)=>b.classList.toggle('active',i===index));stageEl.querySelectorAll('[data-sql-line]').forEach((l,i)=>l.classList.toggle('active',i===index))}
function reveal(index,token){if(token!==runToken)return;const s=scenarios[activeIndex],stageEl=document.querySelector('.scenario-stage');stageEl.querySelectorAll('[data-log-item]').forEach((item,i)=>{if(i===index)item.classList.add('revealed');item.classList.toggle('active',i===index&&item.classList.contains('revealed'));item.classList.toggle('done',i<index&&item.classList.contains('revealed'))});stageEl.querySelectorAll('[data-field-button]').forEach((b,i)=>b.classList.toggle('done',i<=index));stageEl.querySelectorAll('[data-sql-line]').forEach((l,i)=>l.classList.toggle('done',i<=index));stageEl.querySelector('[data-log-progress]').textContent=`${index+1} of ${s.fields.length} evaluated`;const last=index===s.fields.length-1,decision=stageEl.querySelector('[data-decision-badge]');decision.className=last?s.decisionClass:'';decision.textContent=last?s.decision:''}
function flyResult(index,token){if(token!==runToken)return;const s=scenarios[activeIndex],line=document.querySelector(`[data-sql-line="${index}"]`),target=document.querySelector(`[data-log-item="${index}"]`),start=line.getBoundingClientRect(),end=target.getBoundingClientRect(),chip=document.createElement('code'),x=start.left+Math.min(150,start.width*.25),y=start.top+start.height/2-14;chip.className='result-flight';chip.textContent=s.fields[index].value;chip.style.left=`${x}px`;chip.style.top=`${y}px`;document.body.appendChild(chip);line.classList.add('emitting');const dx=end.left+18-x,dy=end.top+18-y,motion=chip.animate([{opacity:0,transform:'translate(0,0) scale(.94)'},{opacity:1,transform:'translate(0,0) scale(1)',offset:.16},{opacity:1,transform:`translate(${dx}px,${dy}px) scale(.9)`,offset:.84},{opacity:0,transform:`translate(${dx}px,${dy}px) scale(.82)`}],{duration:760,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'});motion.onfinish=()=>{chip.remove();line.classList.remove('emitting');reveal(index,token)}}
function reset(){clearRun();const stageEl=document.querySelector('.scenario-stage');stageEl.querySelectorAll('[data-log-item]').forEach(i=>i.classList.remove('revealed','active','done'));stageEl.querySelectorAll('[data-field-button],[data-sql-line]').forEach(i=>i.classList.remove('done'));stageEl.querySelector('[data-log-progress]').textContent=`0 of ${scenarios[activeIndex].fields.length} evaluated`;const decision=stageEl.querySelector('[data-decision-badge]');decision.className='';decision.textContent='';const play=stageEl.querySelector('[data-play]');play.disabled=false;play.innerHTML='<span>▶</span> Evaluate pair';setField(0)}
function play(){reset();const token=runToken,button=document.querySelector('[data-play]');button.disabled=true;button.innerHTML='<span>▶</span> Evaluating…';scenarios[activeIndex].fields.forEach((_,i)=>{const start=160+i*1700;timers.push(setTimeout(()=>setField(i),start));timers.push(setTimeout(()=>flyResult(i,token),start+520))});timers.push(setTimeout(()=>{if(token!==runToken)return;button.disabled=false;button.innerHTML='<span>↻</span> Replay evidence'},160+scenarios[activeIndex].fields.length*1700+400))}
function selectScenario(index){clearRun();const stageEl=document.querySelector('.scenario-stage');stageEl?.classList.add('switching');setTimeout(()=>{activeIndex=index;renderTabs();renderScenario()},140)}
function bindStage(){document.querySelector('[data-reset]').addEventListener('click',reset);document.querySelector('[data-play]').addEventListener('click',play);document.querySelectorAll('[data-field-button]').forEach(button=>button.addEventListener('click',()=>{clearRun();const index=Number(button.dataset.fieldButton),token=runToken;setField(index);timers.push(setTimeout(()=>flyResult(index,token),420))}))}

renderTabs();renderScenario();reset();
document.querySelector('.scenario-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-scenario]');if(button&&Number(button.dataset.scenario)!==activeIndex)selectScenario(Number(button.dataset.scenario))});
window.addEventListener('resize',()=>positionHighlight(Number(document.querySelector('.scenario-stage')?.dataset.field||0)));
}
